INSERT INTO `srt_top_talk` VALUES (/*id*/1000101, /*talk_id*/10001, /*chara_index*/1, /*talk_text*/'哼哼哼，这样就可以让嘉夜夜和老大对我刮目相看了！', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_1_000', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1000201, /*talk_id*/10002, /*chara_index*/1, /*talk_text*/'参加接龙战的时候，要让哥哥也来帮忙', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_1_003', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1000301, /*talk_id*/10003, /*chara_index*/2, /*talk_text*/'不管是什么样的人来找茬，大方应战才是打手该做的！要打就来！', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_1_004', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1000401, /*talk_id*/10004, /*chara_index*/2, /*talk_text*/'用石板玩接龙吗……祈梨这家伙的点子还挺有意思呢', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_1_005', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1000501, /*talk_id*/10005, /*chara_index*/2, /*talk_text*/'不管是接龙还是什么，我都会让你们吃不了兜着走', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_1_006', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1000601, /*talk_id*/10006, /*chara_index*/3, /*talk_text*/'咕么么么……（肚子……饿了）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_1_007', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1000701, /*talk_id*/10007, /*chara_index*/3, /*talk_text*/'咕么么么么（想要 玩接龙）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_1_008', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1000801, /*talk_id*/10008, /*chara_index*/3, /*talk_text*/'咕么么么么！（祈梨 是好人）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_1_009', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1000901, /*talk_id*/10009, /*chara_index*/1, /*talk_text*/'就算对上嘉夜夜，我也不会放水的', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_010', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1000902, /*talk_id*/10009, /*chara_index*/2, /*talk_text*/'那正好！既然要玩，就要全力以赴', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_011', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001001, /*talk_id*/10010, /*chara_index*/1, /*talk_text*/'嘉夜夜，要道歉的话就趁现在吧', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_012', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001002, /*talk_id*/10010, /*chara_index*/2, /*talk_text*/'祈梨你才是，要哭就趁现在哭吧？', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_013', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001101, /*talk_id*/10011, /*chara_index*/1, /*talk_text*/'嘉夜夜，接下来就是智慧的时代了哦？', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_014', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001102, /*talk_id*/10011, /*chara_index*/2, /*talk_text*/'等等！别把我说得像个笨蛋一样啊！', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_015', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001201, /*talk_id*/10012, /*chara_index*/1, /*talk_text*/'来吧，让你见识一下我们的力量', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_016', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001202, /*talk_id*/10012, /*chara_index*/3, /*talk_text*/'咕么！（交给我吧！）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_017', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001301, /*talk_id*/10013, /*chara_index*/1, /*talk_text*/'真乖真乖，可以哦，干得好就奖励你巧克力！', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_018', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001302, /*talk_id*/10013, /*chara_index*/3, /*talk_text*/'咕么！（我 喜欢巧克力）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_019', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001401, /*talk_id*/10014, /*chara_index*/2, /*talk_text*/'喂，祈梨……你该不会忘记最开始的目的了吧？', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_023', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001402, /*talk_id*/10014, /*chara_index*/1, /*talk_text*/'我当然记得了。就是要打倒嘉夜夜，证明我们有多聪明', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_024', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001501, /*talk_id*/10015, /*chara_index*/2, /*talk_text*/'就算是对上祈梨，我也不会让你赢！', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_025', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001502, /*talk_id*/10015, /*chara_index*/1, /*talk_text*/'正合我意，你可别放水哦', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_026', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001601, /*talk_id*/10016, /*chara_index*/2, /*talk_text*/'哼，有两下子嘛', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_027', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001602, /*talk_id*/10016, /*chara_index*/1, /*talk_text*/'嘉夜夜也比我想象中更厉害呢！', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_028', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001701, /*talk_id*/10017, /*chara_index*/2, /*talk_text*/'喂～类龙生物？', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_029', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001702, /*talk_id*/10017, /*chara_index*/3, /*talk_text*/'咕么！？（咿！）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_030', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001801, /*talk_id*/10018, /*chara_index*/2, /*talk_text*/'哎呀……那个时候真是不好意思啦，哈哈哈', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_031', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001802, /*talk_id*/10018, /*chara_index*/3, /*talk_text*/'咕么么么……（嘉夜夜 好可怕）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_032', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001901, /*talk_id*/10019, /*chara_index*/2, /*talk_text*/'话说你……看起来真的好傻啊', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_033', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1001902, /*talk_id*/10019, /*chara_index*/3, /*talk_text*/'咕么……（这话 轮得到你说吗）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_034', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002001, /*talk_id*/10020, /*chara_index*/3, /*talk_text*/'咕么……（肚子饿了 想吃巧克力）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_044', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002002, /*talk_id*/10020, /*chara_index*/2, /*talk_text*/'怎么？困了吗？', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_045', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002101, /*talk_id*/10021, /*chara_index*/3, /*talk_text*/'咕么么（这家伙……很危险）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_046', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002102, /*talk_id*/10021, /*chara_index*/2, /*talk_text*/'嗯？怎么？你想当我的小弟吗？', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_047', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002201, /*talk_id*/10022, /*chara_index*/3, /*talk_text*/'咕么……（嘉夜夜不太会动脑子）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_048', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002202, /*talk_id*/10022, /*chara_index*/2, /*talk_text*/'喂，你刚才在想不礼貌的事情吧？', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_2_049', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002301, /*talk_id*/10023, /*chara_index*/2, /*talk_text*/'话说，这要玩到什么时候才能结束？', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_3_058', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002302, /*talk_id*/10023, /*chara_index*/1, /*talk_text*/'玩到嘉夜夜投降为止！', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_3_059', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002303, /*talk_id*/10023, /*chara_index*/3, /*talk_text*/'咕么么！（快投降！）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_3_060', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002401, /*talk_id*/10024, /*chara_index*/3, /*talk_text*/'咕么！（祈梨 我想要巧克力）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_3_065', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002402, /*talk_id*/10024, /*chara_index*/1, /*talk_text*/'真拿你没办法呢，不可以吃太多哦', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_3_066', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002403, /*talk_id*/10024, /*chara_index*/2, /*talk_text*/'它好像很喜欢那些巧克力伴手礼呢', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_3_067', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002501, /*talk_id*/10025, /*chara_index*/3, /*talk_text*/'咕么！（我不能 输给嘉夜夜！）', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_3_068', /*direction*/2);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002502, /*talk_id*/10025, /*chara_index*/2, /*talk_text*/'哦？怎么？肚子饿了吗？', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_3_069', /*direction*/1);
INSERT INTO `srt_top_talk` VALUES (/*id*/1002503, /*talk_id*/10025, /*chara_index*/1, /*talk_text*/'……根本没办法沟通', /*sheet_name*/'vo_minigame_1004', /*cue_name*/'vo_minigame_1004_top_3_070', /*direction*/2);
